#!/usr/bin/env node
// Generates public/sw-media-bundle.js: the Service Worker's media bundle.
//
//   node scripts/build-sw-media-bundle.mjs              write public/sw-media-bundle.js
//   node scripts/build-sw-media-bundle.mjs --check      exit 1 if it is out of date
//   node scripts/build-sw-media-bundle.mjs --outfile F  write to F instead
//
// What it builds
//   The pure range/decrypt helper (public/js/crypto/messages/attachment-range.js)
//   and the pure media handler core (public/js/sw-media/handler-core.js),
//   bundled into a classic-script IIFE that publishes itself as the global
//   `WireMedia`. The Service Worker loads it with importScripts():
//
//       importScripts('/sw-media-bundle.js');
//       const bytes = await self.WireMedia.decryptChunkRange(...);
//
//   The bundle is a SHIPPED file: scripts/build-sw-manifest.mjs hashes it, the
//   worker verifies that hash while precaching and refuses to install when the
//   served bytes do not match. Regenerate the manifest whenever the bundle
//   changes (same commit, by repo convention).
//
// Reproducibility
//   The output must be byte-identical on every rebuild with the pinned
//   esbuild version, otherwise the manifest hash changes on every deploy and
//   the shell cache is thrown away for nothing. The script therefore refuses
//   to build with an esbuild that is not the version in package-lock.json.
//
//   The bundle is NOT minified: the worker needs readable code (a bundle that
//   throws at evaluation must be diagnosable), and the tests pin its content.

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(here, '..');

const args = process.argv.slice(2);
const check = args.includes('--check');
const outArg = args.indexOf('--outfile');
const outfile = outArg !== -1
    ? path.resolve(args[outArg + 1])
    : path.join(ROOT, 'public', 'sw-media-bundle.js');

const ENTRY_REL = ['public', 'js', 'sw-media', 'bundle-entry.js'].join('/');
const ENTRY = path.join(ROOT, ENTRY_REL);
const LOCKFILE = path.join(ROOT, 'package-lock.json');
const ESBUILD_BIN = path.join(
    ROOT,
    'node_modules',
    '.bin',
    process.platform === 'win32' ? 'esbuild.cmd' : 'esbuild'
);

/** The esbuild version package-lock.json pins. */
function lockedEsbuildVersion() {
    const lock = JSON.parse(fs.readFileSync(LOCKFILE, 'utf8'));
    const entry = lock.packages && lock.packages['node_modules/esbuild'];
    if (!entry || !entry.version) {
        throw new Error('package-lock.json has no version for node_modules/esbuild');
    }
    return entry.version;
}

/** The version of the esbuild binary in node_modules/.bin. */
function installedEsbuildVersion() {
    if (!fs.existsSync(ESBUILD_BIN)) {
        throw new Error(`esbuild is not installed: ${ESBUILD_BIN} is missing`);
    }
    const run = spawnSync(ESBUILD_BIN, ['--version'], {
        encoding: 'utf8',
        shell: process.platform === 'win32',
    });
    if (run.error) throw new Error(`cannot run ${ESBUILD_BIN}: ${run.error.message}`);
    if (run.status !== 0) {
        throw new Error(`esbuild --version failed (${run.status}): ${run.stderr || run.stdout}`);
    }
    return String(run.stdout).trim();
}

function buildTo(target) {
    /*
     * esbuild is run with cwd = ROOT and a RELATIVE entry path: esbuild
     * prints the path of every module relative to its working directory, so
     * an absolute path (or a different working directory) would make the
     * bundle bytes depend on where the build ran. The bundle must be
     * byte-identical on every machine.
     */
    const run = spawnSync(ESBUILD_BIN, [
        ENTRY_REL,
        '--bundle',
        '--format=iife',
        '--global-name=WireMedia',
        '--platform=browser',
        '--target=es2020',
        '--legal-comments=none',
        `--outfile=${target}`,
    ], { encoding: 'utf8', cwd: ROOT, shell: process.platform === 'win32' });

    if (run.error) throw new Error(`cannot run ${ESBUILD_BIN}: ${run.error.message}`);
    if (run.status !== 0) {
        throw new Error(`esbuild failed (${run.status}):\n${run.stderr || run.stdout}`);
    }
}

const locked = lockedEsbuildVersion();
const installed = installedEsbuildVersion();

if (installed !== locked) {
    console.error(
        `esbuild version mismatch: package-lock.json pins ${locked}, ` +
        `node_modules/.bin/esbuild is ${installed}.`
    );
    console.error('The bundle must be built with the pinned version (npm ci) or the');
    console.error('manifest hash changes on every deploy.');
    process.exit(1);
}

if (!fs.existsSync(ENTRY)) {
    console.error(`entry point is missing: ${ENTRY}`);
    process.exit(2);
}

const banner =
    '// GENERATED by scripts/build-sw-media-bundle.mjs - do not edit by hand.\n' +
    '// Source: public/js/sw-media/bundle-entry.js\n' +
    `// esbuild ${locked} (the version pinned in package-lock.json)\n` +
    '// Rebuild: node scripts/build-sw-media-bundle.mjs\n' +
    '// Then regenerate the manifest: node scripts/build-sw-manifest.mjs\n';

if (check) {
    const tmp = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'wire-bundle-')), 'sw-media-bundle.js');
    buildTo(tmp);
    const fresh = banner + fs.readFileSync(tmp, 'utf8');
    fs.rmSync(path.dirname(tmp), { recursive: true, force: true });

    const current = fs.existsSync(outfile) ? fs.readFileSync(outfile, 'utf8') : '';
    if (current !== fresh) {
        console.error('sw-media-bundle.js is out of date.');
        console.error('Regenerate with: node scripts/build-sw-media-bundle.mjs');
        process.exit(1);
    }
    console.log(`sw-media-bundle.js is current (esbuild ${locked}, ${Buffer.byteLength(fresh)} bytes)`);
} else {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'wire-bundle-'));
    const tmp = path.join(tmpDir, 'sw-media-bundle.js');
    try {
        buildTo(tmp);
        const body = banner + fs.readFileSync(tmp, 'utf8');
        fs.mkdirSync(path.dirname(outfile), { recursive: true });
        fs.writeFileSync(outfile, body);
        console.log(
            `sw-media-bundle.js written: ${outfile} ` +
            `(${Buffer.byteLength(body)} bytes, esbuild ${locked})`
        );
    } finally {
        fs.rmSync(tmpDir, { recursive: true, force: true });
    }
}
